INSERT INTO agency_instructions (id, agency_id, general_instructions, required_documents, created_at, updated_at) VALUES (1, 1, '<h3 class="ql-align-center"><strong>A CNH DIGITAL</strong> Será enviado para o seu e-mail com a descrição PORTAL SERVIÇOS</h3><h3 class="ql-align-center"><strong>CNH FISICA: </strong>15 à 20 dias após finalizar as etapas a sua CNH estará disponível para retirada</h3><h3 class="ql-align-center">EMITIR AS TAXAS PELO SITE<strong>: servicos.detran.sc.gov.br/login </strong>ou pelo Aplicativo<strong> Detran SC</strong></h3><p class="ql-align-center"><br></p><h3 class="ql-align-center"><br></h3><h3 class="ql-align-center"><strong>Passo a Passo para gerar as Taxas de Pagamento:</strong></h3><h3 class="ql-align-center"><br></h3><h3 class="ql-align-center">1º Passo: ACESSE<span style="color: var(--WDS-content-external-link);">:</span><strong style="color: var(--WDS-content-external-link);"> https://servicos.detran.sc.gov.br/log</strong><strong>in</strong></h3><h3 class="ql-align-center">2º Passo: <strong>Faça o LOGIN pela sua con</strong><strong style="color: var(--WDS-content-external-link);">ta GOV</strong><strong>.BR</strong></h3><h3 class="ql-align-center">3º Passo<strong>: Clique no botão Consultar Débitos por</strong> <strong>CPF</strong></h3><h3 class="ql-align-center">4º Pass<strong>o: Clique no botão Consultar meu</strong> <strong>CPF</strong></h3><h3 class="ql-align-center"><br></h3><h3 class="ql-align-center">E então será exibida a relação de taxas a pagar, clique ícone para baixar a taxa, ou copie o Código de Barras e realize o pagamento no seu aplicativo do Banco.</h3><h3 class="ql-align-center"><strong>Atenção: A taxa tem que ser paga como BOLETO, e não</strong> <strong>como PIX.</strong></h3>', '', '2025-10-14T12:50:34.170Z', '2026-03-04T15:53:20.621Z');
